"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[3302],{43302:a=>{a.exports=JSON.parse('{"slug":"benzin-podorozhanie-2-1-rublya-import-oktyabr-2026","locale":"zh","title":"能源部提议汽油与柴油每升涨价2.1卢布","description":"能源部提议允许石油企业将汽柴油每升提价2.1卢布，以弥补进口燃料亏损。","blocks":[{"id":"b001","kind":"paragraph","text":"十月，副总理亚历山大\xb7诺瓦克向总理米哈伊尔\xb7米舒斯京转交能源部的燃料价格建议。文件称，即使计入进口补贴，垂直一体化石油公司的加油站销售进口汽油和柴油仍每升亏损13–18卢布。能源部提出两个方案：其一，在这些加油站每升提价2.1卢布；其二，提价1.6卢布，同时将燃料从西北地区铁路运往中部的费用纳入补贴。"},{"id":"b002","kind":"paragraph","text":"进口是因为本国汽油不足，诺瓦克估计缺口约5%。俄罗斯从白俄罗斯及海路进口，包括印度。十月至十二月汽油月进口可能约620千吨，占国内供应16–18%；诺瓦克本人提到的比例约10%。进口至少持续到年底。"},{"id":"b003","kind":"paragraph","text":"设想一家面包房自有面粉不足，只能到商店以两倍价格补货，面包却按原价卖。用外购面粉制作的每个面包都亏钱，损失只能由面包房、财政补贴或支付更高售价的消费者承担。燃料业把这类替代成本称为进口平价。九月进口AI-92每吨108千卢布，国内交易所价格为70.17千；换算每升差约28卢布。"},{"id":"b004","kind":"paragraph","text":"财政进口补贴覆盖部分差额，但不含供应商收取的制裁风险加价和俄罗斯境内配送。财政部反对扩大补贴。市场参与者估计，每升涨2.1卢布可让炼厂每月增加约12十亿卢布收入，而无需预算支出。能源部预计，该方案会使石油公司加油站汽油到年底累计涨11%，即每升7.1卢布；夏季柴油涨10.7%，即8.2卢布。此处专指石油公司加油站，它们夏季涨价慢于独立站。"},{"id":"b005","kind":"paragraph","text":"十月19日所有加油站汽油均价为每升78.04卢布，年初以来上涨20.53%，同期总体通胀6.15%。柴油86.58卢布，上涨13.38%。最近一周汽油下跌0.69%。多数地区排队现象消退，季节需求下降，夏季涨得最快的独立站也开始降价。"},{"id":"b006","kind":"paragraph","text":"政府尚未作出决定。石油公司加油站加价会缩小其亏损，但也抬高价格底线。如果石油公司再提高批发价，向其采购的独立站也必须涨价。原油和进口燃料降价会缩小需弥补的差额；炼厂再遭袭击则会扩大进口份额及每升亏损。"},{"id":"b007","kind":"heading","text":"汽油会每升涨2.1卢布吗？"},{"id":"b008","kind":"paragraph","text":"这仍是能源部建议，政府尚未决定。对象是垂直一体化石油公司的加油站。能源部估计，加价后到年底汽油将涨11%，即每升7.1卢布；夏季柴油涨10.7%，即8.2卢布。"},{"id":"b009","kind":"heading","text":"石油企业为何在进口汽油上亏钱？"},{"id":"b010","kind":"paragraph","text":"本国汽油不足，必须进口。九月进口AI-92每吨108千卢布，国内交易所为70.17千。补贴只覆盖部分差额，不含制裁风险加价和境内配送。因此每升进口燃料亏损13–18卢布。"},{"id":"b011","kind":"heading","text":"哪个方案对司机更便宜？"},{"id":"b012","kind":"paragraph","text":"第二个方案把西北到中部的铁路运输纳入补贴，每升只涨1.6卢布，但预算每月需向石油企业补贴最多2十亿卢布。财政部不支持这一方案。"}],"sources":[{"label":"鼓励汽油进口的成本转嫁给消费者","url":"https://www.kommersant.ru/doc/9045149"},{"label":"石油企业可能在加油站每升提价2.1卢布","url":"https://www.kommersant.ru/doc/9045179"},{"label":"进口燃料供应与定价","url":"https://kommersant.ru/doc/9027583"},{"label":"俄罗斯汽油价格下降0.69%","url":"https://www.interfax.ru/business/1124061"},{"label":"需求不再形成压力","url":"https://rg.ru/2026/10/22/spros-ne-davit.html"}],"sourceBodySha256":"9e2e55674eb7e77b6baeb4a6291922463595de9952c285600f9debb06446d035"}')}}]);